UPDATE `deliverynote`
SET `replySlipCode` = CONCAT('RS-', SUBSTRING(`deliveryNoteCode`, 4))
WHERE `deliveryNoteCode` LIKE 'DN-%'
  AND `deliveryNoteCode` <> 'DN-DEPOSIT'
  AND (`replySlipCode` IS NULL OR TRIM(`replySlipCode`) = '');

